<script setup>
import {ref,computed,watch,onMounted,onUnmounted,nextTick} from 'vue'
import Icon from './components/Icon.vue'
import logoUrl from './assets/logo-panorama.png'
import PlansPage from './components/PlansPage.vue'
import BrokerBenefits from './components/BrokerBenefits.vue'
import TermsPage from './components/TermsPage.vue'
import SuperAdmin from './components/SuperAdmin.vue'
import {getPlan,defaultPlanId,activeCount,canSelectPlan} from './data/plans'
import PropertyCard from './components/PropertyCard.vue'
import PropertyForm from './components/PropertyForm.vue'
import {regions} from './data/regions'
import {seed} from './data/demo'
import {filterProperties,formatPrice,hydrate,stages,statuses,fromApi,toApi,propertyTypes,describeDetails,thumbUrl,leadFromApi,visitFromApi,visitToApi} from './lib/domain'
import {api,PanoramaApiError} from './lib/api'
const routes=['portal','overview','properties','leads','visits','plans','terms','benefits','superadmin']
const initialRoute=location.hash.slice(1)
const key='panorama-workspace-v1'
let raw=null;try{raw=localStorage.getItem(key)}catch{}
const data=ref(hydrate(raw,seed)),page=ref(routes.includes(initialRoute)?initialRoute:'portal'),query=ref(''),operation=ref(''),region=ref(''),type=ref(''),status=ref(''),onlyFavorites=ref(false)
const formOpen=ref(false),editing=ref(null),selected=ref(null),contactOpen=ref(false),visitOpen=ref(false),toast=ref(''),mobileMenu=ref(false),storageError=ref(false)
const contact=ref({name:'',email:'',phone:'',note:'',consent:false}),visit=ref({leadId:'',propertyId:'',date:'',time:'',duration:60,note:''})
const nav=[['overview','grid','Mi panorama'],['properties','home','Propiedades'],['leads','people','Interesados'],['visits','calendar','Agenda'],['plans','grid','Planes y cupos'],['benefits','sun','Marca y beneficios'],['terms','external','Condiciones']]
// Sesión, propiedades, interesados y agenda vienen de la API PHP; favoritos y marca siguen en este navegador.
// En desarrollo, el login viene con la cuenta de prueba de .env.development.local; en producción queda vacío.
const demoLogin=()=>import.meta.env.DEV?{email:import.meta.env.VITE_DEMO_EMAIL||'',password:import.meta.env.VITE_DEMO_PASSWORD||''}:{email:'',password:''}
const session=ref(null),authChecked=ref(false),loginForm=ref(demoLogin()),loginError=ref(''),busy=ref(false),loadError=ref('')
const portfolio=ref([]),publicList=ref([]),subscription=ref(null),leads=ref([]),visits=ref([]),privacyVersion=ref('')
const brokerName=computed(()=>session.value?.memberships?.find(m=>m.organization_id===session.value.organizationId)?.name||'')
const brand=computed(()=>data.value.brokerProfile?.name?data.value.brokerProfile:{name:brokerName.value,logo:''})
const needsAuth=computed(()=>!['portal','plans','terms'].includes(page.value))
const apiMessage=e=>e instanceof PanoramaApiError?e.message:'No se pudo conectar con la API local. Revisa que esté corriendo en el puerto 8080.'
async function loadWorkspace(){const [list,sub,ls,vs]=await Promise.all([api.properties({limit:100}),api.subscription(),api.leads({limit:100}),api.visits({limit:100})]);portfolio.value=list.items.map(fromApi);subscription.value=sub;leads.value=ls.items.map(leadFromApi);visits.value=vs.items.map(visitFromApi)}
async function loadPublic(){try{publicList.value=(await api.properties({limit:100},true)).items.map(fromApi);loadError.value=''}catch(e){loadError.value=apiMessage(e)}}
async function checkSession(){try{session.value=await api.session();await loadWorkspace()}catch(e){session.value=null;if(e.status!==401)loginError.value=apiMessage(e)}finally{authChecked.value=true}}
async function signIn(){busy.value=true;loginError.value='';try{await api.login(loginForm.value.email.trim(),loginForm.value.password);loginForm.value.password='';session.value=await api.session();await loadWorkspace()}catch(e){loginError.value=apiMessage(e)}finally{busy.value=false}}
async function signOut(){try{await api.logout()}catch{}loginForm.value=demoLogin();session.value=null;portfolio.value=[];subscription.value=null;leads.value=[];visits.value=[];navigate('portal')}
onMounted(()=>{checkSession();loadPublic();api.publicConfig().then(c=>{privacyVersion.value=c.personalDataIntakeEnabled?c.privacyNoticeVersion:''}).catch(()=>{})})
const titles={benefits:'Tu marca tiene su propio panorama.',plans:'Un plan para tu próximo panorama.',terms:'Transparencia en cada paso.',overview:'Tu negocio, en perspectiva.',properties:'Cada propiedad, una oportunidad.',leads:'Las personas detrás de cada consulta.',visits:'Un buen encuentro empieza aquí.'}
let timer
function notify(message){toast.value=message;clearTimeout(timer);timer=setTimeout(()=>toast.value='',4000)}
watch(data,()=>{try{localStorage.setItem(key,JSON.stringify({version:1,data:data.value}));storageError.value=false}catch{storageError.value=true}}, {deep:true})
function navigate(value){page.value=value;location.hash=value;mobileMenu.value=false;query.value='';region.value='';operation.value='';type.value='';status.value='';onlyFavorites.value=false}
// #propiedad/{id} abre la ficha desde un enlace compartido.
const sharedId=hash=>hash.match(/^propiedad\/([0-9a-f-]{36})$/i)?.[1]
async function openShared(id){page.value='portal';try{selected.value=fromApi(await api.request('GET',`/public/properties/${id}`))}catch{notify('Esta propiedad ya no está publicada.');history.replaceState(null,'','#portal')}}
function onHash(){const route=location.hash.slice(1);if(sharedId(route))openShared(sharedId(route));else if(routes.includes(route))page.value=route;else if(!route)page.value='portal'}
onMounted(()=>{if(sharedId(initialRoute))openShared(sharedId(initialRoute))})
// Enlace con vista previa propia (título, precio y foto) para WhatsApp y redes.
const shareLink=p=>new URL(`api/v1/public/share/${p.id}`,location.href).href
async function shareProperty(p){const url=shareLink(p),text=`${p.title} · ${formatPrice(p)} · ${p.commune}`;if(navigator.share){try{await navigator.share({title:p.title,text,url})}catch{}return}window.open(`https://wa.me/?text=${encodeURIComponent(`${text}\n${url}`)}`,'_blank','noopener')}
async function copyShare(p){try{await navigator.clipboard.writeText(shareLink(p));notify('Enlace copiado. Al pegarlo en WhatsApp se verá con foto y precio.')}catch{notify(shareLink(p))}}
function closeDetail(){selected.value=null;if(sharedId(location.hash.slice(1)))history.replaceState(null,'','#portal')}
onMounted(()=>window.addEventListener('hashchange',onHash));onUnmounted(()=>{window.removeEventListener('hashchange',onHash);clearTimeout(timer)})
const currentPlan=computed(()=>getPlan(data.value.demoPlanId||defaultPlanId))
const planUsage=computed(()=>subscription.value?.used??activeCount(portfolio.value))
function choosePlan(id){const plan=getPlan(id);if(!canSelectPlan(portfolio.value,plan)){notify('Pausa propiedades antes de reducir los cupos.');return}data.value.demoPlanId=plan.id;notify('Capacidad de demostración actualizada. No se contrató ni cobró un plan.')}
async function changeStatus(p,event){const status=event.target.value;try{Object.assign(p,fromApi(await api.saveProperty(toApi({...p,status}))));await loadWorkspace();loadPublic();notify(`Estado actualizado: ${status}.`)}catch(e){event.target.value=p.status;notify(apiMessage(e))}}
const isPublic=computed(()=>page.value==='portal')
const filtered=computed(()=>filterProperties(isPublic.value?publicList.value:portfolio.value,{query:query.value,operation:operation.value,region:region.value,type:type.value,status:status.value,publicOnly:isPublic.value}).filter(p=>!onlyFavorites.value||data.value.favorites.includes(p.id)))
const published=computed(()=>portfolio.value.filter(p=>p.status==='Publicada'))
const sortedVisits=computed(()=>visits.value.filter(v=>v.status==='scheduled').sort((a,b)=>a.start-b.start))
const upcoming=computed(()=>sortedVisits.value.filter(v=>v.start>=Date.now()))
const newLeads=computed(()=>leads.value.filter(l=>l.stage==='Nuevo').length)
function property(id){return portfolio.value.find(p=>p.id===id)||publicList.value.find(p=>p.id===id)}
function leadName(id){return leads.value.find(l=>l.id===id)?.name||'Sin interesado'}
function edit(p=null){editing.value=p;formOpen.value=true}
async function saveProperty(p){try{await api.saveProperty(toApi(p));formOpen.value=false;notify(p.status==='Publicada'?'Propiedad publicada en el portal.':'Borrador guardado.');await loadWorkspace();loadPublic()}catch(e){notify(e.code==='PUBLICATION_LIMIT'?'No hay cupos disponibles. Guarda un borrador o pausa un aviso publicado.':apiMessage(e))}}
function favorite(id){const i=data.value.favorites.indexOf(id);i<0?data.value.favorites.push(id):data.value.favorites.splice(i,1)}
async function sendContact(){if(!privacyVersion.value){notify('La recepción de consultas no está habilitada.');return}busy.value=true;const c=contact.value;try{await api.inquire(selected.value.id,{name:c.name.trim(),email:c.email.trim(),phone:c.phone.trim(),note:c.note.trim(),consent:c.consent,consentVersion:privacyVersion.value});contactOpen.value=false;contact.value={name:'',email:'',phone:'',note:'',consent:false};notify('Consulta enviada al corredor. Aún no se envían correos de confirmación.');if(session.value)loadWorkspace()}catch(e){notify(apiMessage(e))}finally{busy.value=false}}
function schedule(lead=null){visit.value={leadId:lead?.id||'',propertyId:lead?.propertyId||'',date:'',time:'',duration:60,note:''};visitOpen.value=true}
async function saveVisit(){const body=visitToApi(visit.value,session.value.user.id);if(!body||new Date(body.startsAt)<=new Date()){notify('Elige una fecha y hora futura.');return}try{await api.createVisit(body);visitOpen.value=false;notify('Visita agendada.');await loadWorkspace()}catch(e){notify(apiMessage(e))}}
// Un 409 indica que el registro cambió en otra sesión: se recarga en vez de reintentar.
async function saveLead(l){try{Object.assign(l,leadFromApi(await api.updateLead(l.id,l)))}catch(e){notify(e.status===409?'Este contacto cambió en otra sesión. Recargamos los datos.':apiMessage(e));await loadWorkspace()}}
async function cancelVisit(v){try{await api.cancelVisit(v.id,v.version);notify('Visita cancelada.');await loadWorkspace()}catch(e){notify(apiMessage(e))}}
function exportData(){const blob=new Blob([JSON.stringify({version:1,data:data.value},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='panorama-respaldo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const dateLabel=ms=>new Intl.DateTimeFormat('es-CL',{day:'numeric',month:'short',year:'numeric'}).format(ms)
const timeLabel=ms=>new Intl.DateTimeFormat('es-CL',{hour:'2-digit',minute:'2-digit'}).format(ms)
// Focus containment and restoration for all dialogs, including the property wizard.
let previousFocus=null
const hasDialog=computed(()=>formOpen.value||selected.value||contactOpen.value||visitOpen.value)
watch(hasDialog,async(value)=>{if(value){previousFocus=document.activeElement;await nextTick();document.querySelector('[role="dialog"] button, [role="dialog"] input')?.focus()}else{previousFocus?.focus?.()}})
function dialogKeys(event){if(!hasDialog.value)return;const dialogs=[...document.querySelectorAll('[role="dialog"]')];const dialog=dialogs.at(-1);if(event.key==='Escape'){if(contactOpen.value)contactOpen.value=false;else if(visitOpen.value)visitOpen.value=false;else if(formOpen.value)formOpen.value=false;else closeDetail();return}if(event.key!=='Tab')return;const focusable=[...dialog.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
onMounted(()=>document.addEventListener('keydown',dialogKeys));onUnmounted(()=>document.removeEventListener('keydown',dialogKeys))
</script>
<template>
<a class="skip-link" href="#main">Saltar al contenido</a>
<div class="demo-bar">ENTORNO LOCAL · Datos en la API local · Favoritos y marca solo en este navegador</div>
<div v-if="storageError" class="error" role="alert">No se pudo guardar en este navegador. Exporta un respaldo antes de cerrar.</div>
<header v-if="isPublic" class="public-header"><a class="brand" href="#portal" @click.prevent="navigate('portal')"><img class="brand-logo" :src="logoUrl" alt="Panorama Inmobiliario" width="186" height="44"></a><nav aria-label="Navegación principal"><button class="text-button" @click="operation='Venta'">Comprar</button><button class="text-button" @click="operation='Arriendo'">Arrendar</button><button class="text-button plans-nav" @click="navigate('plans')">Planes</button><button class="button secondary" @click="navigate('overview')">Soy corredor<Icon name="arrow"/></button></nav></header>
<div v-if="page!=='superadmin'" :class="{'workspace':!isPublic&&session}">
<aside v-if="!isPublic&&session" class="sidebar" :class="{expanded:mobileMenu}"><a class="brand" href="#portal" @click.prevent="navigate('portal')"><img class="brand-logo" :src="logoUrl" alt="Panorama Inmobiliario" width="186" height="44"></a><div class="workspace-label">ESPACIO DEL CORREDOR</div><nav aria-label="Panel del corredor"><button v-for="[id,icon,label] in nav" :key="id" :class="{active:page===id}" @click="navigate(id)"><Icon :name="icon"/>{{label}}<span v-if="id==='leads'" class="nav-count">{{newLeads}}</span></button></nav><div class="sidebar-tip"><span class="small-symbol">✦</span><h3>Más orden.<br>Más oportunidades.</h3><p>Tu cartera y tus próximos pasos, en un mismo lugar.</p></div><button class="sidebar-public" @click="navigate('portal')"><Icon name="external"/>Ver portal público</button><div class="account"><span class="avatar">{{session.user.name.slice(0,2).toUpperCase()}}</span><div>{{session.user.name}}<small>{{brokerName}}</small></div><button class="text-button" @click="signOut">Salir</button></div></aside>
<main id="main" :class="isPublic ? 'public-main' : 'dashboard'">
<template v-if="isPublic">
<section class="hero"><div class="hero-copy"><span class="eyebrow"><span class="live-dot"></span> TODO CHILE. NUEVAS POSIBILIDADES.</span><h1>Tu próximo lugar.<br><em>Tu nuevo panorama.</em></h1><p>Hay un espacio para lo que viene.<br>Encuentra el tuyo, de norte a sur.</p><div class="hero-note"><span>01 — 16</span> Una mirada a todas las regiones.</div></div><div class="hero-image" role="img" aria-label="Casa contemporánea con amplios ventanales"><div class="image-caption"><span>ESPACIOS PARA VIVIR MEJOR</span><strong>Un lugar que se siente tuyo.</strong></div></div></section>
<section class="search-panel" aria-label="Buscar propiedades"><div class="operation-tabs"><button :class="{active:!operation}" @click="operation=''">Explorar todo</button><button :class="{active:operation==='Venta'}" @click="operation='Venta'">Comprar</button><button :class="{active:operation==='Arriendo'}" @click="operation='Arriendo'">Arrendar</button></div><div class="search-fields"><label>¿Dónde quieres vivir?<div class="input-icon"><Icon name="search"/><input v-model="query" placeholder="Comuna, sector o palabra clave"></div></label><label>Región<select v-model="region"><option value="">Todo Chile</option><option v-for="r in regions" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>Tipo de propiedad<select v-model="type"><option value="">Todos los tipos</option><option v-for="t in propertyTypes" :key="t">{{t}}</option></select></label><a class="button primary" href="#results">Ver resultados<Icon name="arrow"/></a></div></section>
<section id="results" class="property-section"><div class="section-heading"><div><span class="eyebrow">DESCUBRE TU PRÓXIMO PASO</span><h2>Lugares con posibilidades.</h2><p>{{filtered.length}} propiedades publicadas · Resultados filtrados al instante</p></div><button class="button secondary" :aria-pressed="onlyFavorites" @click="onlyFavorites=!onlyFavorites"><Icon name="heart"/>{{onlyFavorites?'Ver todas':'Mis favoritos'}} ({{data.favorites.length}})</button></div><div v-if="loadError" class="error" role="alert">{{loadError}}</div><div class="property-grid"><PropertyCard v-for="p in filtered" :key="p.id" :property="p" :brand="p.brand" :favorite="data.favorites.includes(p.id)" @favorite="favorite" @open="selected=$event"/></div><div v-if="!filtered.length" class="empty"><Icon name="search"/><h3>Aún no hay propiedades para esta búsqueda.</h3><p>Prueba otra región o elimina algunos filtros.</p><button class="button secondary" @click="query='';region='';type='';operation='';onlyFavorites=false">Limpiar filtros</button></div></section>
<section class="broker-callout"><div><span class="eyebrow">PARA QUIENES CONECTAN PERSONAS Y LUGARES</span><h2>Una mejor perspectiva<br>para tu negocio.</h2><p>Publica, organiza tus contactos y agenda visitas desde tu espacio de corredor.</p></div><button class="button light" @click="navigate('overview')">Explorar panel del corredor<Icon name="arrow"/></button></section><footer class="public-footer"><strong>Panorama Inmobiliario</strong><span>Chile, de norte a sur.</span><button class="text-button" @click="navigate('plans')">Planes</button><button class="text-button" @click="navigate('terms')">Condiciones en preparación</button><small>Prototipo funcional · Avisos ficticios · Sin transacciones ni envíos externos</small></footer>
</template>
<template v-else-if="needsAuth&&!session"><section class="panel login-panel"><span class="eyebrow">ESPACIO DEL CORREDOR</span><h1>Tu cartera te espera.</h1><p v-if="!authChecked">Comprobando tu sesión…</p><form v-else @submit.prevent="signIn"><p>Ingresa con tu cuenta de corredor.</p><p v-if="loginForm.email&&loginForm.email===demoLogin().email" class="notice">Entorno local: cuenta de prueba de Propiedades Mar precargada.</p><div v-if="loginError" class="error" role="alert">{{loginError}}</div><label>Correo<input v-model="loginForm.email" type="email" required autocomplete="username"></label><label>Contraseña<input v-model="loginForm.password" type="password" required autocomplete="current-password"></label><button class="button primary" type="submit" :disabled="busy">{{busy?'Ingresando…':'Ingresar'}}<Icon name="arrow"/></button></form><button class="text-button" @click="navigate('portal')">Volver al portal</button></section></template>
<template v-else>
<header class="dashboard-top"><button class="icon-button mobile-toggle" aria-label="Abrir navegación" :aria-expanded="mobileMenu" @click="mobileMenu=!mobileMenu"><Icon name="menu"/></button><span>Tu espacio de trabajo <span class="muted">/ {{nav.find(n=>n[0]===page)?.[2]}}</span></span><button v-if="session" class="text-button" @click="exportData">Exportar respaldo<Icon name="external"/></button></header>
<div class="dashboard-heading"><div><span class="eyebrow">PANORAMA INMOBILIARIO · CORREDORES</span><h1>{{titles[page] || titles.overview}}</h1><p>Todo lo que necesitas para dar el próximo paso.</p></div><button v-if="!['plans','terms','benefits'].includes(page)" class="button primary" @click="page==='visits'?schedule():edit()"><Icon :name="page==='visits'?'calendar':'plus'"/>{{page==='visits'?'Agendar visita':'Nueva propiedad'}}</button></div>
<div v-if="['overview','properties'].includes(page)" class="quota-strip"><span><strong>{{planUsage}} / {{subscription?.limit??currentPlan.limit}}</strong> publicaciones activas · {{subscription?.status==='pilot'?'Cupo piloto, sin cobro':'Plan '+currentPlan.name+' de demostración'}}</span><button class="text-button" @click="navigate('plans')">Revisar planes<Icon name="arrow"/></button></div>
<PlansPage v-if="page==='plans'" :properties="portfolio" :plan-id="currentPlan.id" @choose="choosePlan" @terms="navigate('terms')" @benefits="navigate('benefits')"/>
<BrokerBenefits v-else-if="page==='benefits'" :properties="portfolio" :profile="data.brokerProfile" @profile="data.brokerProfile=$event" @notify="notify"/>
<TermsPage v-else-if="page==='terms'" @plans="navigate('plans')"/>
<template v-else-if="page==='overview'">
<div class="metrics"><article><span>Propiedades publicadas</span><strong>{{published.length}}<Icon name="home"/></strong><small>{{portfolio.length}} en tu cartera</small></article><article><span>Consultas por atender</span><strong>{{newLeads}}<Icon name="people"/></strong><small>Personas esperando tu respuesta</small></article><article><span>Próximas visitas</span><strong>{{upcoming.length}}<Icon name="calendar"/></strong><small>Tu agenda de aquí en adelante</small></article><article class="metric-accent"><span>Tu siguiente paso</span><strong>Conecta.<Icon name="arrow"/></strong><small>Una buena respuesta abre puertas.</small></article></div>
<div class="overview-grid"><section class="panel"><div class="panel-heading"><h2>Oportunidades recientes</h2><button class="text-button" @click="navigate('leads')">Ver todas<Icon name="arrow"/></button></div><div v-for="l in leads.slice(0,4)" :key="l.id" class="lead-row"><span class="avatar soft">{{l.name.slice(0,1)}}</span><div><strong>{{l.name}}</strong><small>{{property(l.propertyId)?.commune}} · {{property(l.propertyId)?.operation}}</small></div><span class="badge">{{l.stage}}</span><button class="icon-button" :aria-label="'Agendar visita con '+l.name" @click="schedule(l)"><Icon name="calendar"/></button></div><p v-if="!leads.length" class="empty">Todavía no hay consultas.</p></section><section class="panel daily-panel"><span class="eyebrow">EN EL HORIZONTE</span><h2>Tu próxima visita</h2><template v-if="upcoming.length"><strong class="visit-date">{{dateLabel(upcoming[0].start)}}</strong><p>{{timeLabel(upcoming[0].start)}} · {{leadName(upcoming[0].leadId)}}</p><p>{{property(upcoming[0].propertyId)?.title}}</p></template><template v-else><div class="calendar-art"><Icon name="calendar"/></div><h3>Haz espacio para lo que viene.</h3><p>Tu agenda está despejada.<br>Coordina una visita con tus interesados.</p></template><button class="text-button" @click="schedule()">Agendar visita<Icon name="arrow"/></button></section></div>
<div class="section-heading"><div><span class="eyebrow">TU CARTERA</span><h2>Propiedades en movimiento.</h2></div><button class="text-button" @click="navigate('properties')">Ver cartera completa<Icon name="arrow"/></button></div><div class="property-grid"><PropertyCard v-for="p in portfolio.slice(0,3)" :key="p.id" :property="p" :brand="brand" manage @open="selected=$event" @edit="edit"/></div>
</template>
<template v-else-if="page==='properties'"><div class="filter-toolbar"><label class="input-icon"><Icon name="search"/><input v-model="query" aria-label="Buscar en cartera" placeholder="Buscar por título, comuna o código"></label><select v-model="status" aria-label="Estado"><option value="">Todos los estados</option><option v-for="s in statuses" :key="s">{{s}}</option></select><select v-model="operation" aria-label="Operación"><option value="">Venta y arriendo</option><option>Venta</option><option>Arriendo</option></select><span>{{filtered.length}} propiedades</span></div><div class="property-grid"><PropertyCard v-for="p in filtered" :key="p.id" :property="p" :brand="brand" manage @open="selected=$event" @edit="edit"/></div><div v-if="!filtered.length" class="empty"><h3>No hay propiedades que coincidan.</h3><p>Prueba otros filtros o crea una propiedad.</p></div></template>
<template v-else-if="page==='leads'"><div class="notice">Las consultas del portal llegan aquí. Todavía no se envían avisos por correo.</div><section class="panel contacts"><article v-for="l in leads" :key="l.id" class="contact-card"><div class="contact-header"><span class="avatar soft">{{l.name.slice(0,1)}}</span><div><h2>{{l.name}}</h2><p>{{l.email}} {{l.phone?'· '+l.phone:''}}</p></div></div><p class="contact-property">{{property(l.propertyId)?.title || 'Propiedad no disponible'}}</p><label>Estado del contacto<select v-model="l.stage" @change="saveLead(l)"><option v-for="s in stages" :key="s">{{s}}</option></select></label><label>Notas de seguimiento<textarea v-model="l.note" rows="3" maxlength="4000" @change="saveLead(l)" placeholder="Registra acuerdos y próximos pasos"></textarea></label><button class="button secondary" @click="schedule(l)"><Icon name="calendar"/>Agendar visita</button></article><div v-if="!leads.length" class="empty">Las próximas consultas aparecerán aquí.</div></section></template>
<template v-else-if="page==='visits'"><section class="panel"><div class="panel-heading"><h2>Agenda de visitas</h2><span class="muted">Hora local del dispositivo</span></div><div v-for="v in sortedVisits" :key="v.id" class="agenda-row"><div class="agenda-date"><strong>{{dateLabel(v.start)}}</strong><span>{{timeLabel(v.start)}} – {{timeLabel(v.end)}}</span></div><div><h3>{{property(v.propertyId)?.title}}</h3><p>{{leadName(v.leadId)}}</p><small>{{v.note}}</small></div><button class="text-button" @click="cancelVisit(v)">Cancelar visita</button></div><div v-if="!sortedVisits.length" class="empty"><Icon name="calendar"/><h3>Tu próxima visita empieza con una conversación.</h3><p>Selecciona una propiedad y un interesado para agendar.</p><button class="button primary" @click="schedule()">Agendar primera visita</button></div></section></template>
<footer class="dashboard-footer">Panorama Inmobiliario <span>Hecho para abrir nuevas posibilidades.</span></footer>
</template>
</main></div>
<SuperAdmin v-else @exit="navigate('portal')" @notify="notify"/>
<PropertyForm v-if="formOpen" :initial="editing" @close="formOpen=false" @save="saveProperty"/>
<div v-if="selected&&!contactOpen" class="modal-backdrop" @click.self="closeDetail"><section class="modal property-detail" role="dialog" aria-modal="true" aria-labelledby="detail-title"><button class="detail-close icon-button" aria-label="Cerrar propiedad" @click="closeDetail"><Icon name="close"/></button><img v-if="selected.image" class="detail-image" :src="selected.image" :alt="selected.title"><div class="detail-body"><div class="publication-brand"><img v-if="(selected.brand||brand).logo" :src="(selected.brand||brand).logo" alt="" @error="$event.target.style.display='none'"><span>{{(selected.brand||brand).name}}</span></div><span class="eyebrow">{{selected.operation}} · {{selected.type}} · {{selected.id}}</span><h2 id="detail-title">{{selected.title}}</h2><p><Icon name="pin"/>{{selected.commune}}, {{regions.find(r=>r.id===selected.region)?.name}}</p><strong class="detail-price">{{formatPrice(selected)}}</strong><p>{{selected.area}} m² · {{selected.beds}} dormitorios · {{selected.baths}} baños</p><ul v-if="describeDetails(selected.details).length" class="detail-specs"><li v-for="d in describeDetails(selected.details)" :key="d">{{d}}</li></ul><div v-if="selected.images?.length>1" class="detail-gallery"><a v-for="(u,i) in selected.images.slice(1)" :key="u" :href="u" target="_blank" rel="noopener"><img :src="thumbUrl(u)" :alt="`${selected.title}, foto ${i+2}`" loading="lazy" decoding="async"></a></div><p class="detail-description">{{selected.description}}</p><button v-if="isPublic" class="button primary" @click="contactOpen=true">Consultar por esta propiedad<Icon name="arrow"/></button><div v-if="selected.status==='Publicada'" class="share-actions"><button class="button secondary" @click="shareProperty(selected)"><Icon name="external"/>Compartir</button><button class="text-button" @click="copyShare(selected)">Copiar enlace</button></div><template v-else><label>Estado de publicación<select :value="selected.status" @change="changeStatus(selected,$event)"><option v-for="s in statuses" :key="s">{{s}}</option></select></label><button class="button primary" @click="edit(selected);selected=null">Editar propiedad</button></template></div></section></div>
<div v-if="contactOpen" class="modal-backdrop" @click.self="contactOpen=false"><form class="modal" role="dialog" aria-modal="true" aria-labelledby="contact-title" @submit.prevent="sendContact"><div class="modal-heading"><h2 id="contact-title">Conversemos sobre este lugar.</h2><button class="icon-button" type="button" aria-label="Cerrar consulta" @click="contactOpen=false"><Icon name="close"/></button></div><p>{{selected.title}}</p><div class="notice">Tu consulta llega al panel del corredor que publica este aviso. No se envían correos ni WhatsApp.</div><label>Nombre<input v-model="contact.name" required maxlength="100" autocomplete="name"></label><label>Correo<input v-model="contact.email" type="email" required autocomplete="email"></label><label>Teléfono (opcional)<input v-model="contact.phone" type="tel" autocomplete="tel" maxlength="30"></label><label>¿Qué te gustaría saber?<textarea v-model="contact.note" required rows="3" maxlength="2000"></textarea></label><label class="consent"><input v-model="contact.consent" type="checkbox" required>Acepto que el corredor use estos datos para responder mi consulta (aviso de privacidad en borrador, versión {{privacyVersion||'no disponible'}}).</label><button class="button primary" type="submit" :disabled="busy||!privacyVersion">{{busy?'Enviando…':'Enviar consulta'}}<Icon name="arrow"/></button></form></div>
<div v-if="visitOpen" class="modal-backdrop" @click.self="visitOpen=false"><form class="modal" role="dialog" aria-modal="true" aria-labelledby="visit-title" @submit.prevent="saveVisit"><div class="modal-heading"><h2 id="visit-title">Agendar una visita</h2><button class="icon-button" type="button" aria-label="Cerrar agenda" @click="visitOpen=false"><Icon name="close"/></button></div><label>Interesado<select v-model="visit.leadId" required @change="visit.propertyId=leads.find(l=>l.id===visit.leadId)?.propertyId||''"><option value="">Selecciona una persona</option><option v-for="l in leads.filter(x=>x.email)" :key="l.id" :value="l.id">{{l.name}}</option></select></label><label>Propiedad<select v-model="visit.propertyId" required :disabled="!!visit.leadId"><option value="">Selecciona una propiedad</option><option v-for="p in portfolio" :key="p.id" :value="p.id">{{p.title}}</option></select></label><div class="form-grid"><label>Fecha<input v-model="visit.date" type="date" required></label><label>Hora<input v-model="visit.time" type="time" required></label><label>Duración<select v-model="visit.duration"><option :value="30">30 minutos</option><option :value="60">1 hora</option><option :value="90">1 hora y media</option><option :value="120">2 horas</option></select></label></div><label>Notas<textarea v-model="visit.note" rows="3" maxlength="2000"></textarea></label><div class="notice">La propiedad se toma de la consulta del interesado. No se enviarán invitaciones ni recordatorios.</div><button class="button primary" type="submit">Guardar visita<Icon name="check"/></button></form></div>
<div v-if="toast" class="toast" role="status">{{toast}}</div>
</template>
